```sql
SELECT T1.Airline FROM airlines AS T1 INNER JOIN flights AS T2 ON T1.uid = T2.Airline WHERE T2.SourceAirport = 'APG' AND T2.DestAirport = 'CVO' GROUP BY T1.Airline HAVING COUNT(DISTINCT T2.Airline) > 1;

